/**
 * Server-side media index: src/content/media.json (generated by scripts/prepare-media.mjs).
 * Import this only from server components — client components use media-client.ts,
 * so the image index and blur placeholders never ship as JavaScript.
 */
import 'server-only';
import data from '@/content/media.json';
import type { VideoEntry } from './media-client';
export { fullVideo, clip, cmedia } from './media-client';
export type { VideoEntry, LoopEntry, ClipEntry } from './media-client';

export type ImageEntry = {
  src: string; // base path, e.g. /media/img/photo-15-01  →  -640.avif / -1280.webp …
  widths: number[];
  width: number;
  height: number;
  aspect: number;
  blurDataURL: string;
  source?: string;
};

type MediaIndex = {
  images: Record<string, ImageEntry>;
  videos: Record<string, VideoEntry & { base: string; sourceWidth: number; sourceHeight: number }>;
  stills?: Record<string, string[]>;
};

export const media = data as unknown as MediaIndex;

export function img(key: string): ImageEntry {
  const e = media.images[key];
  if (!e) throw new Error(`[media] unknown image "${key}" — run npm run media`);
  return e;
}
export const hasImg = (key: string) => key in media.images;

/** Nearest generated width ≥ requested (or the largest). */
export function pickWidth(widths: number[], want: number) {
  return widths.find((w) => w >= want) ?? widths[widths.length - 1];
}

/** Best single URL for an image at a given width (used for CSS backgrounds / OG / JSON-LD). */
export function imgUrl(key: string, want = 1280, fmt: 'avif' | 'webp' = 'webp') {
  const e = img(key);
  return `${e.src}-${pickWidth(e.widths, want)}.${fmt}`;
}

export const fmtTime = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
